class Node:
    def __init__(self, val, next=None, random=None):
        self.val = val
        self.next = next
        self.random = random


def build_random_list(pairs):
    if not pairs:
        return None
    nodes = [Node(val) for val, _ in pairs]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    for i, (_, r) in enumerate(pairs):
        nodes[i].random = nodes[r] if r != -1 else None
    return nodes[0]


def list_to_pairs(head):
    nodes = []
    node = head
    while node:
        nodes.append(node)
        node = node.next
    index = {id(n): i for i, n in enumerate(nodes)}
    return [
        [n.val, index[id(n.random)] if n.random else -1]
        for n in nodes
    ]


def copy_random_list(pairs):
    head = build_random_list(pairs)

    if not head:
        return list_to_pairs(None)

    mapping = {}
    node = head
    while node:
        mapping[node] = Node(node.val)
        node = node.next

    node = head
    while node:
        mapping[node].next = mapping.get(node.next)
        mapping[node].random = mapping.get(node.random)
        node = node.next

    return list_to_pairs(mapping[head])

